SELECT item.icode, item.customicode, item.name, item.localitemname AS localitemname, item.manfcode, item.packunits, item.purprice, CASE (SELECT g.salepriceinitemlist FROM dbo.groups AS g WHERE (g.groupcode = $1)) WHEN 2 THEN item.saleprice2 WHEN 3 THEN item.saleprice3 WHEN 4 THEN item.saleprice4 WHEN 5 THEN item.saleprice5 ELSE item.saleprice END AS saleprice, manufacturer.name, (SELECT name FROM dbo.genericitem WHERE (genericitem.genericcode = item.genericcode)) AS genericname, (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail WHERE (godowndetail.icode = item.icode)) AS stock, CASE WHEN ((SELECT salegodownstrategy FROM dbo.groups WHERE (groupcode = $1)) = 2) THEN (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail WHERE ((godowndetail.icode = item.icode) AND (godowndetail.gcode = item.gcode))) ELSE (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail, (SELECT DISTINCT gcode FROM dbo.groupallowedgodown WHERE ((groupallowedgodown.groupcode = $1) AND (groupallowedgodown.module = 1))) AS t WHERE ((godowndetail.icode = item.icode) AND (godowndetail.gcode = t.gcode))) END AS sstock, CASE WHEN ((SELECT purchasegodownstrategy FROM dbo.groups WHERE (groupcode = $1)) = 2) THEN (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail WHERE ((godowndetail.icode = item.icode) AND (godowndetail.gcode = item.gcode))) ELSE (SELECT sum(godowndetail.currqty) FROM dbo.godowndetail, (SELECT DISTINCT gcode FROM dbo.groupallowedgodown WHERE ((groupallowedgodown.groupcode = $1) AND (groupallowedgodown.module = 3))) AS t WHERE ((godowndetail.icode = item.icode) AND (godowndetail.gcode = t.gcode))) END AS pstock, itempacking.name AS packing, item.packingdesc AS packingdesc, item.icatcode, item.iccode, item.packcode, item.itemalertcode, (SELECT ia.itemalerttypecode FROM dbo.itemalert AS ia WHERE (ia.itemalertcode = item.itemalertcode)) AS itemalerttypecode, item.restricted, item.location, item.transitstock AS transitstock, (SELECT ia.bgcolor FROM dbo.itemalert AS ia WHERE (ia.itemalertcode = item.itemalertcode)) AS bgcolor FROM dbo.item LEFT JOIN dbo.itempacking ON ((item.packcode = itempacking.packcode)), dbo.manufacturer WHERE ((item.active = 1) AND (manufacturer.manfcode = item.manfcode)) ORDER BY item.name